package com.masterclass.inventory.controller; import com.masterclass.inventory.dto.ProductDtos.*; import com.masterclass.inventory.service.ProductService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/products") @RequiredArgsConstructor public class ProductController { private final ProductService service; @PostMapping public ResponseEntity<ProductResponse> create(@Valid @RequestBody ProductRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping public List<ProductResponse> list(@RequestParam(required=false) String q){return service.list(q);} @GetMapping("/{id}") public ProductResponse get(@PathVariable Long id){return service.get(id);} @PutMapping("/{id}") public ProductResponse update(@PathVariable Long id,@Valid @RequestBody ProductRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable Long id){service.delete(id);} }
